  if (maxX >= 10) return { g: 'A', label: 'Massive', emoji: '🚀' };
  if (maxX >= 5) return { g: 'B', label: 'Big', emoji: '🔥' };
  if (maxX >= 2) return { g: 'C', label: 'Solid', emoji: '💪' };
  if (maxX >= 0.5) return { g: 'D', label: 'Small', emoji: '🌱' };
  if (maxX >= 0) return { g: 'E', label: 'Flat', emoji: '➖' };
